// Description: C header of the spi_master register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-16
#ifndef SPI_MASTER_REGS_H
#define SPI_MASTER_REGS_H
#define SPI_MASTER_REGS_ID_OFFSET 0x00u
#define SPI_MASTER_REGS_VERSION_OFFSET 0x04u
#define SPI_MASTER_REGS_DATE_OFFSET 0x08u
#define SPI_MASTER_REGS_ID_VALUE 0x5350494Du   /* "SPIM" */
#define SPI_MASTER_REGS_CTRL_OFFSET 0x10u   /* RW */
#define SPI_MASTER_REGS_CTRL_RESET 0x00000000u
#define SPI_MASTER_REGS_CTRL_EN_SHIFT 0u
#define SPI_MASTER_REGS_CTRL_EN_MASK 0x00000001u
#define SPI_MASTER_REGS_CTRL_CPOL_SHIFT 1u
#define SPI_MASTER_REGS_CTRL_CPOL_MASK 0x00000002u
#define SPI_MASTER_REGS_CTRL_CPHA_SHIFT 2u
#define SPI_MASTER_REGS_CTRL_CPHA_MASK 0x00000004u
#define SPI_MASTER_REGS_CTRL_LSB_FIRST_SHIFT 3u
#define SPI_MASTER_REGS_CTRL_LSB_FIRST_MASK 0x00000008u
#define SPI_MASTER_REGS_CTRL_CS_SELECT_SHIFT 8u
#define SPI_MASTER_REGS_CTRL_CS_SELECT_MASK 0x0000FF00u
#define SPI_MASTER_REGS_DIV_OFFSET 0x14u   /* RW */
#define SPI_MASTER_REGS_WORD_LEN_OFFSET 0x18u   /* RW */
#define SPI_MASTER_REGS_WORD_LEN_RESET 0x00000008u
#define SPI_MASTER_REGS_STATUS_OFFSET 0x1Cu   /* CMD */
#define SPI_MASTER_REGS_STATUS_RESET 0x00000000u
#define SPI_MASTER_REGS_STATUS_BUSY_SHIFT 0u
#define SPI_MASTER_REGS_STATUS_BUSY_MASK 0x00000001u
#define SPI_MASTER_REGS_STATUS_RX_OVERRUN_SHIFT 1u
#define SPI_MASTER_REGS_STATUS_RX_OVERRUN_MASK 0x00000002u
#define SPI_MASTER_REGS_STATUS_RX_LEVEL_SHIFT 16u
#define SPI_MASTER_REGS_STATUS_RX_LEVEL_MASK 0xFFFF0000u
#endif /* SPI_MASTER_REGS_H */
